# `{name}` directly after a letter, `\`, `_` or `^` is a LaTeX group, not a placeholder.
const _BRMD_PLACEHOLDER = r"(?<![A-Za-z\\_^])\{([A-Za-z_]+)\}"
_brmd_placeholders(text) = Set(Symbol(m[1]) for m in eachmatch(_BRMD_PLACEHOLDER, text))

"""
    description_texts(locale::Symbol=:en; texts...) -> BRMDescriptionTexts

The [`BRMDescriptionTexts`](@ref) for `locale` (`:en` or `:de`), with any of its
texts replaced by keyword:

```julia
const DE = description_texts(:de; effective_priors="A-priori-Verteilungen:")
description = brm_description(d; labels, texts=DE)
brm_description_markdown(description)   # German throughout
```

An unknown locale or text name throws an `ArgumentError`, and so does a text
that drops a placeholder the English text has or adds one it lacks.
"""
function description_texts(locale::Symbol=:en; texts...)
    haskey(_BRMD_TEXT_LOCALES, locale) || throw(ArgumentError(string("description_texts: unknown locale ",
        repr(locale), "; available: ", join(repr.(keys(_BRMD_TEXT_LOCALES)), ", "))))
    english = _BRMD_TEXT_LOCALES.en
    names = keys(english)
    for name in keys(texts)
        name in names || throw(ArgumentError(string("description_texts: unknown text ", repr(name),
            "; texts are ", join(names, ", "))))
    end
    merged = merge(getfield(_BRMD_TEXT_LOCALES, locale), (; (k => string(v) for (k, v) in pairs(texts))...))
    for name in names
        haskey(merged, name) || throw(ArgumentError(string("description_texts: locale ", repr(locale),
            " has no text ", repr(name))))
        expected = _brmd_placeholders(english[name])
        found = _brmd_placeholders(merged[name])
        found == expected || throw(ArgumentError(string("description_texts: ", name, " takes ",
            isempty(expected) ? "no placeholders" : join(("{$p}" for p in sort!(collect(expected))), ", "),
            "; got ", isempty(found) ? "none" : join(("{$p}" for p in sort!(collect(found))), ", "))))
    end
    BRMDescriptionTexts(locale, NamedTuple{names}(Tuple(merged[name] for name in names)))
end

const _BRMD_EN_TEXTS = description_texts(:en)

function Base.show(io::IO, t::BRMDescriptionTexts)
    base = getfield(_BRMD_TEXT_LOCALES, t.locale)
    changed = count(name -> t.texts[name] != base[name], keys(t.texts))
    print(io, "description_texts(", repr(t.locale), iszero(changed) ? "" : "; $changed replaced texts", ")")
end

# A text with its placeholders filled in. Inserted values are not rescanned.
_brmd_text(t::BRMDescriptionTexts, name::Symbol; values...) =
    replace(getfield(t.texts, name), _BRMD_PLACEHOLDER => m -> string(values[Symbol(m[2:end-1])]))
